-- Risk flag on messages (BR-MSG-008, AC-033-3, issue #23): a message that asks for money before a
-- visit or for identity documents is marked, and the person who receives it sees the warning above
-- it. The message is never blocked or changed (AC-033-2). The list of phrases lives in
-- core/text-checks.js; risk_check below is generated from it and tests/unit/risk-parity.test.js
-- fails if they drift.

create extension if not exists unaccent with schema extensions;

-- GENERATED by tests/fixtures/risk-sql.js from RISK_PHRASES in core/text-checks.js. Do not edit by hand.
-- BR-MSG-008: the same normalized text and the same list as riskCheck.
create or replace function public.risk_check(p_text text)
returns boolean
language sql
stable
set search_path = public, extensions
as $$
  with h as (
    select ' ' || btrim(regexp_replace(replace(replace(lower(extensions.unaccent(coalesce(p_text, ''))), '’', ''), '''', ''),
      '[^a-z0-9$]+', ' ', 'g')) || ' ' as t
  )
  select exists (
    select 1 from h, unnest(array['bank transfer', 'transfer the money', 'transfer money', 'transfer the deposit', 'transfer the bond', 'send money', 'send the money', 'send the deposit', 'send the bond', 'send a deposit', 'pay the deposit', 'pay a deposit', 'pay the bond upfront', 'pay upfront', 'pay up front', 'pay in advance', 'holding deposit', 'holding fee', 'deposit to hold', 'deposit to secure', 'secure the room', 'secure the place', 'payid', 'pay id', 'paypal', 'western union', 'moneygram', 'wire transfer', 'wise transfer', 'gift card', 'gift cards', 'bitcoin', 'crypto', 'usdt', 'bsb', 'account number', 'passport', 'drivers licence', 'drivers license', 'driver licence', 'driver license', 'licence photo', 'license photo', 'payslip', 'payslips', 'pay slip', 'pay slips', 'bank statement', 'bank statements', 'medicare card', 'tax file number', 'tfn', 'copy of your id', 'photo of your id', 'picture of your id', 'send your id', 'id documents', 'id document', 'proof of identity']::text[]) p
    where h.t like '% ' || p || ' %'
  ) or exists (
    select 1 from h, unnest(array[' (send|pay|transfer|wire)( me| us)?( the| a| your)? (deposit|bond|money|rent|holding fee) ']::text[]) r
    where h.t ~ r
  )
$$;

-- Only the trigger calls it; the web checks with core/text-checks.js.
revoke execute on function public.risk_check(text) from public, anon, authenticated;

-- The same trigger as 20261106090000_conversations.sql, now also setting risk_flag. The value the
-- web sends is ignored: the column has no insert grant and is always computed here.
create or replace function public.messages_before_insert()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  c public.conversations;
  other uuid;
begin
  select * into c from public.conversations where id = new.conversation_id for update;
  if new.sender_id is not null then
    if exists (select 1 from public.profiles where id = new.sender_id and status = 'suspended') then
      raise exception 'suspended' using errcode = '42501';
    end if;
    other := case when new.sender_id = c.seeker_id then c.host_id else c.seeker_id end;
    if other is not null and exists (
      select 1 from public.blocks where blocker_id = other and blocked_id = new.sender_id
    ) then
      raise exception 'blocked' using errcode = '42501';
    end if;
  end if;

  new.risk_flag := public.risk_check(new.body);
  new.created_at := now();
  update public.conversations set
    last_message_at = new.created_at,
    first_reply_at = case
      when new.sender_id = c.host_id and c.first_reply_at is null then new.created_at
      else c.first_reply_at end,
    seeker_read_at = case when new.sender_id = c.seeker_id then new.created_at else c.seeker_read_at end,
    host_read_at = case when new.sender_id = c.host_id then new.created_at else c.host_read_at end
  where id = c.id;
  return new;
end;
$$;
